max_reduce_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <math_constants.h>

#include <cute/tensor.hpp>

using namespace cute;

__global__ void __launch_bounds__(256) max_reduce_dim_kernel(
    const float* __restrict__ X,
    float* __restrict__ Y,
    int outer,
    int R,
    int inner,
    int64_t total)
{
  // CUTE views of the contiguous input/output as (outer, R, inner) -> (outer, inner)
  Tensor mX = make_tensor(
      make_gmem_ptr(X),
      make_shape(outer, R, inner),
      make_stride((int64_t)R * inner, (int64_t)inner, Int<1>{})
  );
  Tensor mY = make_tensor(
      make_gmem_ptr(Y),
      make_shape(outer, inner),
      make_stride((int64_t)inner, Int<1>{})
  );
  // Block-cooperative split along the reduction dimension R. Each block owns
  // a 32-column tile of one outer slice: threadIdx.x covers 32 consecutive
  // inner columns (fully coalesced 128-byte loads) while threadIdx.y splits
  // R into 8 strided slices. Compared to one-thread-per-output this gives
  // 8x more thread-level parallelism and 8x shorter fmaxf dependency
  // chains; partial maxima are combined through shared memory.
  const int tpo = (inner + 31) >> 5;
  const int64_t num_tiles = (int64_t)outer * tpo;
  const int y = (int)threadIdx.y;
  __shared__ float smax[8][32];
  (void)total;
  for (int64_t b = blockIdx.x; b < num_tiles; b += gridDim.x) {
    const int o = (int)(b / tpo);
    const int tile = (int)(b - (int64_t)o * tpo);
    const int c = (tile << 5) + (int)threadIdx.x;
    const bool valid = c < inner;
    float a0 = -CUDART_INF_F;
    float a1 = -CUDART_INF_F;
    float a2 = -CUDART_INF_F;
    float a3 = -CUDART_INF_F;
    if (valid) {
      const float* p = &mX(o, 0, c);
      const int64_t rstride = (int64_t)inner;
      int r = y;
      for (; r + 24 < R; r += 32) {
        a0 = fmaxf(a0, p[(int64_t)(r + 0) * rstride]);
        a1 = fmaxf(a1, p[(int64_t)(r + 8) * rstride]);
        a2 = fmaxf(a2, p[(int64_t)(r + 16) * rstride]);
        a3 = fmaxf(a3, p[(int64_t)(r + 24) * rstride]);
      }
      for (; r < R; r += 8) {
        a0 = fmaxf(a0, p[(int64_t)r * rstride]);
      }
    }
    smax[y][threadIdx.x] = fmaxf(fmaxf(a0, a1), fmaxf(a2, a3));
    __syncthreads();
    if (y == 0 && valid) {
      float m = smax[0][threadIdx.x];
#pragma unroll
      for (int j = 1; j < 8; ++j) {
        m = fmaxf(m, smax[j][threadIdx.x]);
      }
      mY(o, c) = m;
    }
    __syncthreads();
  }
}

torch::Tensor max_reduce_dim(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  const int64_t rank = x.dim();
  TORCH_CHECK(rank >= 1, "x must have at least 1 dimension");

  int64_t d = dim;
  if (d < 0) d += rank;
  TORCH_CHECK(d >= 0 && d < rank, "dim out of range");

  auto xc = x.contiguous();

  int64_t outer = 1;
  for (int64_t i = 0; i < d; ++i) outer *= xc.size(i);
  const int64_t R = xc.size(d);
  TORCH_CHECK(R > 0, "reduction dimension must be non-empty");
  int64_t inner = 1;
  for (int64_t i = d + 1; i < rank; ++i) inner *= xc.size(i);

  std::vector<int64_t> out_sizes;
  out_sizes.reserve(rank - 1);
  for (int64_t i = 0; i < rank; ++i) {
    if (i != d) out_sizes.push_back(xc.size(i));
  }

  auto y = torch::empty(out_sizes, xc.options());
  const int64_t total = outer * inner;
  if (total == 0) return y;

  TORCH_CHECK(outer <= INT32_MAX && R <= INT32_MAX && inner <= INT32_MAX,
              "reduction extents too large for this kernel");

  const int threads_x = 32;
  const int threads_y = 8;
  const int64_t tiles_per_o = (inner + threads_x - 1) / threads_x;
  int64_t blocks = outer * tiles_per_o;
  if (blocks < 1) blocks = 1;
  if (blocks > 2147483647LL) blocks = 2147483647LL;
  dim3 block((unsigned)threads_x, (unsigned)threads_y);
  dim3 grid((unsigned)blocks);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  max_reduce_dim_kernel<<<grid, block, 0, stream>>>(
      xc.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)outer,
      (int)R,
      (int)inner,
      total
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "max_reduce_dim_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

